function is_undulating(n) {
  // Convert the number to a string to easily access each digit
  const strN = n.toString();

  // Check if the number has at least 3 digits
  if (strN.length < 3) {
    return false;
  }

  // Check if the number is undulating
  for (let i = 0; i < strN.length - 1; i++) {
    if (strN[i] !== strN[i + 1]) {
      return false;
    }
  }

  return true;
}

function is_undulating(n){
    if (n.toString().length < 3) return false; // A number with less than 3 digits cannot be undulating

    let isIncreasing = true;
    let isDecreasing = true;

    for (let i = 0; i < n.toString().length - 1; i++) {
        if (n.toString()[i] > n.toString()[i + 1]) {
            isIncreasing = false;
        }
        if (n.toString()[i] < n.toString()[i + 1]) {
            isDecreasing = false;
        }
    }

    return isIncreasing || isDecreasing;
}

function find_Rotations(str){
  let rotations = 0;
  let originalStr = str;
  while (rotations < str.length) {
    str = str + str[0]; // Rotate the string by appending the first character to the end
    rotations++;
    if (str === originalStr) {
      return rotations;
    }
  }
  return rotations; // This line will never be reached if the string has no rotations
}

