function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let h;
    let s;
    let v = max;

    if (delta === 0) {
        h = s = v = 0; // Black or white
    } else {
        s = delta / v;

        if (r === max) {
            h = (g - b) / delta; // Red is primary
        } else if (g === max) {
            h = 2 + (b - r) / delta; // Green is primary
        } else {
            h = 4 + (r - g) / delta; // Blue is primary
        }

        h *= 60; // Convert to degrees
        if (h < 0) h += 360;
    }

    return [h, s, v];
}

function rgb_to_hsv(r, g, b) {
  // Convert RGB to HSV
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);
  let delta = max - min;

  let hue;
  if (delta === 0) {
    hue = 0;
  } else if (max === r) {
    hue = (60 * ((g - b) / delta)) % 360;
  } else if (max === g) {
    hue = (60 * ((b - r) / delta)) + 120;
  } else if (max === b) {
    hue = (60 * ((r - g) / delta)) + 240;
  }

  let saturation;
  if (delta === 0) {
    saturation = 0;
  } else {
    saturation = (delta / max) * 100;
  }

  let value = max * 100;

