function maxAverageOfPath(cost){
  const N = cost.length;
  const dp = new Array(N).fill().map(() => new Array(N).fill(0));

  // Fill the DP table
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      if (i === 0 && j === 0) {
        dp[i][j] = cost[i][j];
      } else if (i === 0) {
        dp[i][j] = dp[i][j - 1] + cost[i][j];
      } else if (j === 0) {
        dp[i][j] = dp[i - 1][j] + cost[i][j];
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j];
      }
    }
  }

  // Calculate the maximum average
  let maxAverage = Number.MIN_SAFE_INTEGER;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const totalCost = dp[i][j];
      const pathLength = i + j + 1;
      const average = totalCost / pathLength;
      maxAverage = Math.max(maxAverage, average);
    }
  }

  return maxAverage;
}

