function rearrange_bigger(n) {
  const digits = n.toString().split('');
  const sortedDigits = digits.slice().sort((a, b) => b - a);
  const length = digits.length;

  for (let i = length - 2; i >= 0; i--) {
    if (digits[i] < sortedDigits[i + 1]) {
      const j = sortedDigits.indexOf(digits[i + 1]);
      const temp = digits[i];
      digits[i] = digits[j];
      digits[j] = temp;
      const remainingDigits = digits.slice(i + 1).sort((a, b) => a - b);
      return parseInt(digits.join(''), 10);
    }
  }

  return -1; // No bigger number can be formed
}

function rearrange_bigger(n) {
  // Convert the number to an array of digits
  const digits = Array.from(String(n), Number);

  // Find the largest index i such that digits[i] < digits[i + 1]
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such index is found, the number is the largest possible permutation
  if (i === -1) {
    return -1;
  }

  // Find the largest index j such that digits[j] > digits[i]
  let j = digits.length - 1;
  while (digits[j] <= digits[i]) {
    j--;
  }

  // Swap digits[i] and digits[j]
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Sort the remaining digits in ascending order
  digits.splice(i + 1).sort((a, b) => a - b);

  // Convert the array of digits back to a number
  return parseInt(digits.join(''), 10);
}

