function histogram(test) {
  if (test === "") {
    return {};
  }

  const letterCounts = {};
  const words = test.split(" ");

  for (const word of words) {
    for (const letter of word) {
      letterCounts[letter] = (letterCounts[letter] || 0) + 1;
    }
  }

  let maxCount = 0;
  const mostFrequentLetters = {};

  for (const letter in letterCounts) {
    if (letterCounts[letter] > maxCount) {
      maxCount = letterCounts[letter];
      mostFrequentLetters = {};
      mostFrequentLetters[letter] = maxCount;
    } else if (letterCounts[letter] === maxCount) {
      mostFrequentLetters[letter] = maxCount;
    }
  }

  return mostFrequentLetters;
}

