function min_Jumps(steps, d){
    // Calculate the maximum distance that can be reached with the given number of steps
    const maxDistance = steps * steps;

    // Calculate the minimum number of jumps required to reach the point (d, 0)
    let jumps = 0;
    while (d > 0) {
        d -= maxDistance;
        jumps++;
    }

    // If d is still greater than 0, it means the point (d, 0) is unreachable
    if (d > 0) {
        return -1;
    }

    return jumps;
}

