function eulerian_num(n, m) {
    if (n < m || m < 0) {
        return 0; // Eulerian number is not defined for n < m or m < 0
    }

    if (n === 0 && m === 0) {
        return 1; // Eulerian number for (0, 0) is 1
    }

    if (n === 1) {
        return m === 0 ? 1 : 0; // Eulerian number for (1, 0) is 1, (1, 1) is 0
    }

    if (m === 1) {
        return n === 0 ? 0 : 1; // Eulerian number for (0, 1) is 0, (1, 1) is 1
    }

    let result = 0;
    for (let i = 0; i <= m; i++) {
        result += (-1) ** i * Math.comb(n, i) * Math.comb(m, n - i);
    }

    return result;
}

