function group_tuples(Input){
  // Check if the input is an array of arrays
  if (!Array.isArray(Input) || Input.length === 0 || !Input.every(arr => Array.isArray(arr) && arr.length > 0)) {
    throw new Error("Input must be an array of arrays with at least one element in each array.");
  }

  // Find the common first element
  const firstElements = Input.map(arr => arr[0]);
  const commonFirstElement = firstElements.find(element => firstElements.every(arr => arr === element));

  return commonFirstElement;
}

function group_tuples(Input) {
  // Sort each array within the input array
  Input.forEach(arr => arr.sort());

  // Find the first common element by comparing the first elements of each array
  let commonElement = Input[0][0];

  // Iterate through the remaining arrays to find the common element
  for (let i = 1; i < Input.length; i++) {
    while (Input[i][0] !== commonElement) {
      Input[i].shift();
      if (Input[i].length === 0) {
        return null; // No common element found
      }
    }
    commonElement = Input[i][0];
  }

  return commonElement;
}

function make_palindrome(string) {
  if (string === "") return "";

  let reversedString = string.split("").reverse().join("");

  for (let i = 0; i < string.length; i++) {
    let suffix = string.slice(i);
    if (suffix === reversedString.slice(0, suffix.length)) {
      return string + reversedString.slice(suffix.length);
    }
  }

  return string + reversedString;
}

