function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]]; // Right, Down, Up, Left
    const visited = new Set();
    const queue = [[grid[0][0], 0, [grid[0][0]]]]; // [value, steps, path]

    while (queue.length > 0) {
        const [currentValue, steps, path] = queue.shift();

        if (steps === k) {
            return path;
        }

        for (const [dx, dy] of directions) {
            const newRow = currentRow + dy;
            const newCol = currentCol + dx;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow},${newCol}`)) {
                visited.add(`${newRow},${newCol}`);
                queue.push([grid[newRow][newCol], steps + 1, [...path, grid[newRow][newCol]]]);
            }
        }
    }

    return []; // In case no path is found
}

function minPath(grid, k) {
    const n = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const visited = new Array(n).fill().map(() => new Array(n).fill(false));
    const path = [];
    const directionsQueue = [[0, 0, 0]]; // [row, col, steps]

    while (directionsQueue.length > 0) {
        const [row, col, steps] = directionsQueue.shift();

        if (steps === k) {
            path.push(grid[row][col]);
            continue;
        }

        if (steps < k) {
            visited[row][col] = true;

            for (const [dr, dc] of directions) {
                const newRow = row + dr;
                const newCol = col + dc;

                if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited[newRow][newCol]) {
                    directionsQueue.push([newRow, newCol, steps + 1]);
                }
            }
        }
    }

    return path;
}

