function max_sum(arr) {
  const n = arr.length;
  const dp = Array.from({ length: n }, () => Array(n).fill(0));
  const dpRev = Array.from({ length: n }, () => Array(n).fill(0));

  // Fill dp array
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) continue;
      if (arr[i] < arr[j]) {
        dp[i][j] = Math.max(dp[i][j], dp[j][i] + arr[i]);
      }
    }
  }

  // Fill dpRev array
  for (let i = n - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (i === j) continue;
      if (arr[i] < arr[j]) {
        dpRev[i][j] = Math.max(dpRev[i][j], dpRev[j][i] + arr[i]);
      }
    }
  }

  // Find the maximum sum of bitonic subsequence
  let maxSum = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i !== j) {
        maxSum = Math.max(maxSum, dp[i][j] + dpRev[i][j] - arr[i]);
      }
    }
  }

  return maxSum;
}

function max_sum(arr){
  const n = arr.length;
  const dpInc = new Array(n).fill(0);
  const dpDec = new Array(n).fill(0);

  for(let i = 0; i < n; i++){
    for(let j = 0; j < i; j++){
      if(arr[i] > arr[j]){
        dpInc[i] = Math.max(dpInc[i], dpInc[j] + arr[i]);
      }
    }
    for(let j = n - 1; j > i; j--){
      if(arr[i] > arr[j]){
        dpDec[i] = Math.max(dpDec[i], dpDec[j] + arr[i]);
      }
    }
  }

  let maxSum = 0;
  for(let i = 0; i < n; i++){
    maxSum = Math.max(maxSum, dpInc[i] + dpDec[i] - arr[i]);
  }

  return maxSum;
}

