function amicable_numbers_sum(limit){
  let sum = 0;
  for (let i = 1; i <= limit; i++) {
    let divisors = divisorsSum(i);
    if (divisors > i && divisorsSum(divisors) === i) {
      sum += i;
    }
  }
  return sum;
}

function divisorsSum(n) {
  let sum = 1;
  for (let i = 2; i <= Math.sqrt(n); i++) {
    if (n % i === 0) {
      sum += i;
      if (i !== n / i) {
        sum += n / i;
      }
    }
  }
  return sum;
}

function amicable_numbers_sum(limit) {
