    if (i % 2 === 0) {
      sequence.push(sequence[i - 1] + sequence[i - 2]);
    } else {
      sequence.push(sequence[i - 1] + sequence[i - 2] + sequence[i + 1]);
    }
  }

  return sequence.slice(0, n + 1);
}

function rgb_to_hsv(r, g, b) {
  // Convert RGB to HSV
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;

  let h;
  let s;
  let v = max;

  if (delta === 0) {
    h = 0;
    s = 0;
  } else {
    s = delta / v;

    const rc = (max - r) / delta;
    const gc = (max - g) / delta;
    const bc = (max - b) / delta;

    if (r === max) {
      h = (bc - gc) / delta;
    } else if (g === max) {
      h = 2 + (rc - bc) / delta;
    } else {
      h = 4 + (gc - rc) / delta;
    }

    h *= 60;
    if (h < 0) h += 360;
  }

  return { h, s, v };
}

function rgb_to_hsv(r, g, b) {
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;

  let hue;
  if (delta === 0) {
    hue = 0;
  } else if (max === r) {
    hue = (60 * ((g - b) / delta)) % 360;
  } else if (max === g) {
    hue = (60 * ((b - r) / delta)) + 120;
  } else {
    hue = (60 * ((r - g) / delta)) + 240;
  }

  const saturation = (max === 0) ? 0 : delta / max;
  const value = max;

  return { hue, saturation, value };
}

function next_power_of_2(n) {
  // Calculate the logarithm of n to the base 2
  const log2 = Math.log2(n);
  // Round up to the nearest whole number
  const ceilLog2 = Math.ceil(log2);
  // Return 2 raised to the power of the ceiling logarithm
  return 2 ** ceilLog2;
}

