function get_max_sum(n) {
  if (n === 1) return 1;

  const memo = new Map();

  function dfs(num) {
    if (memo.has(num)) return memo.get(num);

    const result = Math.max(
      dfs(num / 2) + dfs(num / 3) + dfs(num / 4) + dfs(num / 5),
      num
    );

    memo.set(num, result);
    return result;
  }

  return dfs(n);
}

