function occurance_substring(text, pattern) {
  if (typeof text !== 'string' || typeof pattern !== 'string') {
    return undefined;
  }

  let count = 0;
  let position = 0;

  while ((position = text.indexOf(pattern, position)) !== -1) {
    count++;
    position++; // Move to the next character after the found pattern
  }

  return { count, position };
}

