function reverse_Array_Upto_K(input, k){
  if (k > input.length) {
    throw new Error("k must be less than or equal to the length of the input array");
  }

  let start = 0;
  let end = k - 1;

  while (start < end) {
    let temp = input[start];
    input[start] = input[end];
    input[end] = temp;
    start++;
    end--;
  }

  return input;
}

function encode(message) {
  const vowels = 'aeiouAEIOU';
  const shiftedVowels = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ';
  let encodedMessage = '';

  for (let char of message) {
    if (vowels.includes(char)) {
      let index = vowels.indexOf(char);
      let shiftedIndex = (index + 2) % vowels.length;
      encodedMessage += shiftedVowels[shiftedIndex];
    } else {
      encodedMessage += char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
    }
  }

  return encodedMessage;
}

function encode(message) {
    const vowels = 'aeiouAEIOU';
    const vowelsMap = new Map([
        ['a', 'c'], ['e', 'g'], ['i', 'k'], ['o', 'q'], ['u', 's'],
        ['A', 'C'], ['E', 'G'], ['I', 'K'], ['O', 'Q'], ['U', 'S']
    ]);

    return message.split('').map(char => {
        if (vowels.includes(char)) {
            const nextVowel = vowelsMap.get(char);
            return nextVowel;
        } else if (char >= 'a' && char <= 'z') {
            return char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
        }
        return char;
    }).join('');
}

