function find_combinations(test_list) {
  const result = [];
  const backtrack = (index, currentSum, currentCombination) => {
    if (currentSum === 0) {
      result.push([...currentCombination]);
      return;
    }
    if (index === test_list.length || currentSum < 0) {
      return;
    }
    currentCombination.push(test_list[index]);
    backtrack(index + 1, currentSum - test_list[index], currentCombination);
    currentCombination.pop();
    backtrack(index + 1, currentSum, currentCombination);
  };
  backtrack(0, 0, []);
  return result;
}

function find_combinations(test_list) {
    let result = [];
    const n = test_list.length;
    const sum = test_list.reduce((a, b) => a + b, 0);
    const currentSum = 0;
    const currentCombination = [];

    function backtrack(start) {
        if (currentSum === sum) {
            result.push([...currentCombination]);
            return;
        }
        for (let i = start; i < n; i++) {
            currentCombination.push(test_list[i]);
            currentSum += test_list[i];
            backtrack(i + 1);
            currentCombination.pop();
            currentSum -= test_list[i];
        }
    }

    backtrack(0);
    return result;
}

