function modp(n, p) {
  if (p === 1) return 0; // Edge case: p is 1, any number modulo 1 is 0
  let result = 1;
  for (let i = 0; i < n; i++) {
    result = (result * n) % p; // Multiply result by n, then modulo p
  }
  return result;
}

function check_dict_case(dict){
  if (Object.keys(dict).length === 0) return false;

  const keys = Object.keys(dict);
  const isLowercase = keys.every(key => key === key.toLowerCase());
  const isUppercase = keys.every(key => key === key.toUpperCase());

  return isLowercase || isUppercase;
}

function check_dict_case(dict){
    if (Object.keys(dict).length === 0) return false;

    const keys = Object.keys(dict);
    const lowerCaseKeys = keys.filter(key => typeof key === 'string' && key.toLowerCase() === key);
    const upperCaseKeys = keys.filter(key => typeof key === 'string' && key.toUpperCase() === key);

    return lowerCaseKeys.length === keys.length || upperCaseKeys.length === keys.length;
}

function sum_squares(lst) {
    let sum = 0;
    for (let i = 0; i < lst.length; i++) {
        if (i % 3 === 0) {
            sum += lst[i] * lst[i]; // Square the entry
        } else if (i % 4 === 0) {
            sum += lst[i] * lst[i] * lst[i]; // Cube the entry
        }
    }
    return sum;
}

